mapper.select:
select *
from attempt_answer
where attempt_no = #{attemptNo}
  and question_no = #{questionNo}

mapper.update:
update attempt_answer
set
    option_no = #{optionNo},
    is_correct = #{isCorrect}
where attempt_no = #{attemptNo}
  and question_no = #{questionNo}

mapper.delete:
delete from attempt_answer
where attempt_no = #{attemptNo}
  and question_no = #{questionNo}
